import { TreeMapRootNode } from '../types/treemap.js';

export /**
 * Function to copy and sort tree 2 levels deep
 * @param rootNode - TreeMap root node
 * @returns - sorted TreeMap root node
 */
const getSortedTree = (rootNode: TreeMapRootNode) => {
  const clusters = [...(rootNode.nodes ?? [])].sort(
    (a, b) => a.value - b.value,
  );

  const children = clusters.map((cluster) => {
    return {
      ...cluster,
      children: [...(cluster.nodes ?? [])].sort((a, b) => b.value - a.value),
    };
  });
  return { ...rootNode, children };
};
